export function getCat1And2Seeds() {
  const seeds = [];

  // 1A: 45 distritos de Lima y Callao
  LIMA_CALLAO_DISTRICTS.forEach((d, idx) => {
    const cleanSlug = d.name
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");

    seeds.push({
      slug: `que-comer-en-${cleanSlug}-mercados-huariques-y-platos-tradicionales`,
      title: `Qué Comer en ${d.name}: Guía de Mercados, Huariques Tradicionales y Platos Bandera`,
      category: "rutas-lima-y-callao",
      categoryName: "Rutas de Lima y Callao",
      focusKeyword: `que comer en ${d.name.toLowerCase()} huariques y mercados`,
      layoutVariant: "geo-lima-huarique",
      schemaType: "ItemList",
      badgeLabel: `📍 Guía Local: ${d.name}`,
      imageHint: idx % 2 === 0 ? "ceviche" : "lomo",
      geoInfo: {
        locationName: d.name,
        regionLabel: d.zone,
        marketsNote: d.markets,
        emblemDish: d.dish,
        priceRange: d.price,
        climateTip: d.climate,
      },
      summary: `Recorrido gastronómico por ${d.name} (${d.zone}): qué insumos comprar en ${d.markets}, cuáles son sus huariques clásicos para disfrutar de ${d.dish}, precios referenciales en Soles (${d.price}) y cómo preparar su receta insignia en casa.`,
    });
  });

  // 1B: 15 rutas temáticas de Lima
  LIMA_THEMATIC_ROUTES.forEach((r) => {
    seeds.push({
      slug: r.slug,
      title: r.title,
      category: "rutas-lima-y-callao",
      categoryName: "Rutas de Lima y Callao",
      focusKeyword: r.title.split(":")[0].toLowerCase(),
      layoutVariant: "geo-lima-huarique",
      schemaType: "ItemList",
      badgeLabel: `📍 Ruta Lima: ${r.loc}`,
      imageHint: r.slug.includes("pesquero") || r.slug.includes("callao") ? "pescado" : "platos",
      geoInfo: {
        locationName: r.loc,
        regionLabel: "Ruta Gastronómica de Lima y Callao",
        marketsNote: r.markets,
        emblemDish: r.dish,
        priceRange: r.price,
        climateTip: r.tip,
      },
      summary: `${r.title}. Incluye mapa de puestos en ${r.markets}, lista de precios en Soles (${r.price}), consejos de compra inteligente y preparación paso a paso de ${r.dish}.`,
    });
  });

  // 1C: 20 especialidades adicionales de barrios y mercados de Lima (Total Cat 1 = 80)
  EXTRA_LIMA_SPECIALTIES.forEach((e) => {
    seeds.push({
      slug: e.slug,
      title: e.title,
      category: "rutas-lima-y-callao",
      categoryName: "Rutas de Lima y Callao",
      focusKeyword: e.title.split(":")[0].toLowerCase(),
      layoutVariant: "geo-lima-huarique",
      schemaType: "ItemList",
      badgeLabel: `📍 Huariques: ${e.loc}`,
      imageHint: e.slug.includes("ceviche") ? "ceviche" : "arroz",
      geoInfo: {
        locationName: e.loc,
        regionLabel: "Tradición Limeña",
        marketsNote: e.markets,
        emblemDish: e.dish,
        priceRange: e.price,
        climateTip: e.tip,
      },
      summary: `Guía culinaria de ${e.loc}: dónde encontrar ${e.dish} en ${e.markets}, precios actualizados (${e.price}) y el secreto técnico de los cocineros limeños para replicarlo en casa.`,
    });
  });

  // 2A: 30 Ciudades: Guía de Mercados de Abastos y Picanterías
  PROVINCIAS_PERU.forEach((p) => {
    const cleanCity = p.city
      .toLowerCase()
      .normalize("NFD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-|-$/g, "");

    seeds.push({
      slug: `mercados-picanterias-y-donde-comer-en-${cleanCity}-guia-gastronomica`,
      title: `Mercados de Abastos y Picanterías en ${p.city}: Qué Comer y Qué Insumos Regionales Comprar`,
      category: "cocina-regional-ciudades",
      categoryName: "Cocina Regional y Picanterías",
      focusKeyword: `picanterias y mercados en ${p.city.toLowerCase()}`,
      layoutVariant: "geo-provincia-tradicion",
      schemaType: "ItemList",
      badgeLabel: `🇵🇪 Ruta Regional: ${p.city}`,
      imageHint: "regional",
      geoInfo: {
        locationName: p.city,
        regionLabel: p.region,
        marketsNote: p.markets,
        emblemDish: p.dish,
        priceRange: p.price,
        climateTip: p.climate,
      },
      summary: `Guía gastronómica de ${p.city} (${p.region}): recorrido por ${p.markets}, platos de picantería imperdibles como ${p.dish}, precios en Soles (${p.price}) y secretos de fogón regional.`,
    });

    // 2B: 30 Ciudades: Recetario de Olla de Barro, Fogón y Despensa Local (30 más = 60)
    seeds.push({
      slug: `despensa-insumos-y-recetas-de-fogon-en-${cleanCity}-sabor-regional`,
      title: `La Despensa Culinaria de ${p.city}: Insumos Autóctonos, Técnicas de Fogón y Receta Insignia`,
      category: "cocina-regional-ciudades",
      categoryName: "Cocina Regional y Picanterías",
      focusKeyword: `insumos y cocina tradicional de ${p.city.toLowerCase()}`,
      layoutVariant: "geo-provincia-tradicion",
      schemaType: "Recipe",
      badgeLabel: `🏺 Fogón de ${p.city}`,
      imageHint: "guiso",
      geoInfo: {
        locationName: p.city,
        regionLabel: p.region,
        marketsNote: p.markets,
        emblemDish: p.dish,
        priceRange: p.price,
        climateTip: p.climate,
      },
      summary: `Análisis de los ingredientes endémicos de ${p.city} (${p.region}), cómo seleccionarlos en ${p.markets} y cómo cocinar paso a paso ${p.dish.split(",")[0]} respetando la técnica ancestral.`,
    });
  });

  // 2C: 20 Desayunos Regionales y Platos de Calendario Picantero (Total Cat 2 = 80)
  REGIONAL_BREAKFASTS_AND_TRADITIONS.forEach((b) => {
    seeds.push({
      slug: b.slug,
      title: b.title,
      category: "cocina-regional-ciudades",
      categoryName: "Cocina Regional y Picanterías",
      focusKeyword: b.title.split(":")[0].toLowerCase(),
      layoutVariant: "geo-provincia-tradicion",
      schemaType: "Recipe",
      badgeLabel: `🇵🇪 Tradición de ${b.city}`,
      imageHint: "tradicional",
      geoInfo: {
        locationName: b.city,
        regionLabel: b.region,
        marketsNote: b.markets,
        emblemDish: b.dish,
        priceRange: b.price,
        climateTip: "Cocina regional preparada desde la madrugada con insumos frescos de valle y picantería.",
      },
      summary: `${b.title}. Conoce la historia en ${b.markets}, los ingredientes exactos para lograr ${b.dish} y la receta detallada paso a paso.`,
    });
  });

  return seeds;
}
